  bottom: clamp(0px, var(--breakpoint-simulation) * 1000, 86%);
  --breakpoint: 500px;
  --breakpoint-simulation: (100vw - var(--breakpoint));

  position: fixed;

  /* Напишите функцию clamp вычисляющую положение элемента */
}
